inline TruckWorld TruckFK(const TruckPose& pose,const TruckPositions& positions,const TruckPositions* scales=nullptr){using namespace DriverIK;TruckWorld world;TruckPositions inherited{};for(unsigned i=0;i<72;++i){unsigned p=kTruckParents[i];world.q[i]=p==255?pose[i]:Product(world.q[p],pose[i]);auto point=positions[i];if(p!=255)for(unsigned axis=0;axis<3;++axis)point[axis]*=inherited[p][axis];world.p[i]=p==255?point:Add(world.p[p],Rotate(world.q[p],point));for(unsigned axis=0;axis<3;++axis)inherited[i][axis]=(p==255?-1.f:inherited[p][axis])*(scales?(*scales)[i][axis]:1.f);}return world;}
